// newPlatformPluginMutation creates new mutation for the PlatformPlugin entity.
func newPlatformPluginMutation(c config, op Op, opts ...platformpluginOption) *PlatformPluginMutation {
	m := &PlatformPluginMutation{
		config:        c,
		op:            op,
		typ:           TypePlatformPlugin,
		clearedFields: make(map[string]struct{}),
	}
	for _, opt := range opts {
		opt(m)
	}
	return m
}

// withPlatformPluginID sets the ID field of the mutation.
func withPlatformPluginID(id string) platformpluginOption {
	return func(m *PlatformPluginMutation) {
		var (
			err   error
			once  sync.Once
			value *PlatformPlugin
		)
		m.oldValue = func(ctx context.Context) (*PlatformPlugin, error) {
			once.Do(func() {
				if m.done {
					err = errors.New("querying old values post mutation is not allowed")
				} else {
					value, err = m.Client().PlatformPlugin.Get(ctx, id)
				}
			})
			return value, err
		}
		m.id = &id
	}
}

// withPlatformPlugin sets the old PlatformPlugin of the mutation.
func withPlatformPlugin(node *PlatformPlugin) platformpluginOption {
	return func(m *PlatformPluginMutation) {
		m.oldValue = func(context.Context) (*PlatformPlugin, error) {
			return node, nil
		}
		m.id = &node.ID
	}
}

